   int64_t total_time = timestamp + duration;
   int64_t hit_count = 0;
   int64_t total_time_per_hit = 0;

   // Evaluate the hits and time spent on the website
   for (int64_t time : times) {
      if (time > 300) {
         hit_count++;
         total_time_per_hit += time;
