Product search_product(Product product) {
    int low = 0;
    int high = products.size() - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (products[mid] == product) {
            return products[mid];
        } else if (products[mid] < product) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return Product();
}

